export default defineProblem({
  signature: {
    kind: 'function',
    name: 'reconstructQueue',
    params: [{ name: 'people', type: 'int[][]' }],
    returns: 'int[][]',
  },
  examples: [
    {
      args: [
        [
          [6, 1],
          [2, 4],
          [3, 0],
          [6, 0],
          [4, 1],
        ],
      ],
      expected: [
        [3, 0],
        [6, 0],
        [4, 1],
        [6, 1],
        [2, 4],
      ],
      explanation:
        'The person of height 4 has one person of height ≥ 4 in front (the first 6). The second 6 has one (the first 6). The 2 has everyone else in front.',
    },
    {
      args: [
        [
          [7, 2],
          [8, 1],
          [9, 0],
        ],
      ],
      expected: [
        [9, 0],
        [8, 1],
        [7, 2],
      ],
    },
    {
      args: [
        [
          [5, 2],
          [5, 0],
          [5, 1],
        ],
      ],
      expected: [
        [5, 0],
        [5, 1],
        [5, 2],
      ],
      explanation: 'People of equal height count each other.',
    },
  ],
  tests: hiddenTests,
  solution: {
    javascript: `function reconstructQueue(people) {
  // Tallest first; among equal heights, fewer people in front first.
  const sorted = [...people].sort((a, b) => b[0] - a[0] || a[1] - b[1])
  const queue = []
  // Everyone already placed is at least as tall, so inserting at index k puts exactly
  // k of them in front. Shorter people inserted later don't change that count.
  for (const person of sorted) queue.splice(person[1], 0, person)
  return queue
}`,
    python: `class Solution:
    def reconstructQueue(self, people: List[List[int]]) -> List[List[int]]:
        # Tallest first; among equal heights, fewer people in front first.
        queue = []
        # Everyone already placed is at least as tall, so inserting at index k puts exactly
        # k of them in front. Shorter people inserted later don't change that count.
        for person in sorted(people, key=lambda p: (-p[0], p[1])):
            queue.insert(person[1], person)
        return queue`,
  },
})
